/**
 * @param {number[]} parent
 * @param {string} s
 * @return {number[]}
 */
var findSubtreeSizes = function(parent, s) {
    const n = parent.length;
    const newParent = parent.slice();

    for (let i = 1; i < n; i++) {
        let p = parent[i];

        while (s[i] !== s[p] && p !== -1) {
            p = parent[p];
        }

        if (p !== -1) {
            newParent[i] = p;
        }
    }

    const graph = Array.from({ length: n }, () => []);

    for (let i = 1; i < n; i++) {
        graph[newParent[i]].push(i);
    }

    const dp = Array(n).fill(1);

    const explore = (node) => {
        for (const con of graph[node]) {
            dp[node] += explore(con);
        }

        return dp[node];
    };

    explore(0);

    return dp;
};

/**
 * @param {number[]} parent
 * @param {string} s
 * @return {number[]}
 */
var findSubtreeSizes = function(parent, s) {
    const n = parent.length;
    const graph = Array.from({ length: n }, () => []);

    for (let i = 1; i < n; i++) {
        graph[parent[i]].push(i);
    }

    const last = new Int32Array(26).fill(-1);
    const res = Array(n).fill(1);

    const dfs = (node) => {
        const char = s.charCodeAt(node) - 97;
        const prev = last[char];
        const p = prev === -1 ? parent[node] : prev;

        last[char] = node;
        for (const child of graph[node]) {
            dfs(child);
        }
        last[char] = prev;

        if (p !== -1) {
            res[p] += res[node];
        }
    };

    dfs(0);

    return res;
};
